Rules.InvariantScript:
Set(
    CodeExpired,
    If(
        DateDiff(
            gblTimeCodeWasSent,
            Now(),
            TimeUnit.Minutes
        ) > 5,
        true,
        false
    )
);
Set(
    CodeError,
    If(
        Value(txtRegistrationCode.Text) <> gblRegistrationCodeSent,
        true,
        false
    )
);
If(
    CodeExpired,
    false;
    Notify(
        "Code has expired. Click resend for another code",
        NotificationType.Error,
        4000
    ),
    If(
        CodeError,
        false;
        Notify(
            "Incorrect code. Try again",
            NotificationType.Error,
            4000
        ),
        If(
            CodeExpired = false And CodeError = false,
            ForAll(
                colNewUser,
                Patch(
                    LoginDemo,
                    Defaults(LoginDemo),
                    {
                        Titre: Name,
                        UserName: UserName,
                        EmailAddress: Email,
                        Password: Password
                    }
                )
            );
            Navigate(
                HomeScreen,
                ScreenTransition.Fade
            );
            Reset(txtRegistrationCode)
        );
        Notify(
            "Registration successful. Please login",
            NotificationType.Information,
            3000
        )
    )
);
Reset(txtFullName);
Reset(txtUsername);
Reset(txtEmailAddress);
Reset(txtPassword);
Reset(txtConfirmPassword);

// Enregistre l'heure d'envoi du code
Set(
    gblTimeCodeWasSent,
    Now()
);

// Génère un code aléatoire à 6 chiffres
Set(
    gblRegistrationCodeSent,
    RandBetween(111111, 999999)
);

// Envoie de l'e-mail via Outlook
Office365Outlook.SendEmailV2(
    gblNewUserEmail,
    "Account Recovery Code",
    "<div style='background-color: #f5f5f5; width: 650px; height: 400px; border: 2px solid black; padding-bottom: 30px; font-weight:600; color: #0c5c00'>
        <div style='background-color: #638b2c ;  height: 60px; text-align: center; color: #f5f5f5; font-weight: 900; padding: 15px;font-size:2em; font-family: Trebuchet MS'>
            APPLICATION REGISTRATION
        </div>
        <div style='font-size:2em; font-family: Trebuchet MS; padding: 20px; background-color:#f5f5f5; color: #057f3f'>
            <br> Hello " & gblNewUserFullName & ",<br><br> Please complete your account registration using the code below. 
            <div style='background-color: #f5f5f5; height: 60px; text-align: center; color: #057f3f; font-weight: 900; padding: 15px; font-size:2em; font-family: Trebuchet MS'>
                " & gblRegistrationCodeSent & "
            </div>
        </div>
    </div>",
    {
        Importance: "Normal",
        IsHtml: true
    }
);

// Notification utilisateur
Notify(
    "A code has been sent to your email",
    NotificationType.Information,
    4000
);

